wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10564941614198500)
,p_plug_name=>unistr('Gesti\00F3n de Usuarios')
,p_static_id=>unistr('gesti\00F3n-de-usuarios')
,p_title=>unistr('  Gesti\00F3n de Usuarios')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select u.usuario_id,',
'       u.username,',
'       u.email,',
'       u.estado,',
'       u.fecha_creacion,',
'       e.nombre_empresa as empresa,',
'       r.codigo_rol as rol,',
'       case',
'         when u.bloqueado_hasta > sysdate then ''BLOQUEADO''',
'         when upper(nvl(u.estado, ''#'')) = ''PENDIENTE'' then ''PENDIENTE''',
'         when upper(nvl(u.estado, ''#'')) in (''ACTIVO'', ''A'', ''1'') then',
'              ''ACTIVO'' || case when nvl(u.debe_cambiar_clave, ''N'') = ''S''',
'                                then '' (CLAVE POR CAMBIAR)'' end',
'         else ''INACTIVO''',
'       end as situacion,',
'       case',
'         when u.bloqueado_hasta > sysdate then ''BLOQUEADO''',
'         when upper(nvl(u.estado, ''#'')) = ''PENDIENTE'' then ''PENDIENTE''',
'         when upper(nvl(u.estado, ''#'')) in (''ACTIVO'', ''A'', ''1'') then ''ACTIVO''',
'         else ''INACTIVO''',
'       end as situacion_clase',
'  from usuario u',
'  left join empresas e on e.id_empresa = u.id_empresa',
'  left join syn_roles r on r.id_rol = u.rol_id',
' where u.id_empresa = (select x.id_empresa from usuario x',
'                        where upper(x.username) = upper(:APP_USER))',
'    or u.id_empresa is null',
' order by lower(u.username)'))
,p_include_rowid_column=>false
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
