,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT p.id_presupuesto AS seleccionar,',
'       p.id_presupuesto AS editar,',
'       p.id_presupuesto AS print_link,',
'       p.id_presupuesto AS gastos_link,',
'       p.folio,',
'       c.razon_social,',
'       c.rif,',
'       p.fecha_emision,',
'       p.fecha_vencimiento,',
'       p.cod_moneda,',
'       p.subtotal,',
'       p.impuesto_iva,',
'       p.total,',
'       p.estado',
'  FROM presupuestos p',
'  JOIN clientes c',
'    ON c.id_cliente = p.id_cliente',
'   AND c.id_empresa = p.id_empresa',
' WHERE p.estado NOT IN (''CANCELADO'')',
'   AND p.id_empresa IN (SELECT u.id_empresa FROM usuario u',
'                        WHERE upper(u.username) = upper(:APP_USER)',
'                          AND u.estado IN (''ACTIVO'', ''A'', ''1''))',
' ORDER BY p.id_presupuesto DESC'))
,p_plug_source_type=>'NATIVE_IR'
);
