wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(12541094704283236)
,p_plug_name=>'Resumen Financiero'
,p_static_id=>'totales'
,p_title=>'Resumen Financiero'
,p_region_css_classes=>'u-textRight'
,p_region_template_options=>'#DEFAULT#'
,p_region_attributes=>'style="text-align: right; font-weight: bold; font-size: 16px;"'
,p_plug_template=>3372714138756020509
,p_plug_display_sequence=>50
,p_plug_grid_column_span=>4
,p_plug_display_column=>9
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_id_presupuesto    NUMBER := fn_clean_num(:P5_ID_PRESUPUESTO);',
'    v_subtotal_bruto    NUMBER := 0;',
'    v_total_descuento   NUMBER := 0;',
'    v_subtotal_neto     NUMBER := 0;',
'    v_iva               NUMBER := 0;',
'    v_total             NUMBER := 0;',
'    v_gasto_real        NUMBER := 0;',
'    v_desviacion        NUMBER := 0;',
'    v_color             VARCHAR2(10) := ''#137333'';',
'    v_moneda            VARCHAR2(5) := ''---'';',
'    v_tasa              NUMBER := 1;',
'    v_html              VARCHAR2(4000);',
'BEGIN',
'    -- Misma tarjeta que la pagina 8 (Facturacion): moneda en las etiquetas,',
'    -- mascara FM y total tomado de las lineas. Antes usaba ''$999,999,990.00''',
'    -- y otra formula, y por eso no cuadraba a la vista con facturacion.',
'    IF v_id_presupuesto > 0 THEN',
'        BEGIN',
'            SELECT cod_moneda, NVL(tipo_cambio, 1)',
'              INTO v_moneda, v_tasa',
'              FROM presupuestos',
'             WHERE id_presupuesto = v_id_presupuesto;',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN NULL;',
'        END;',
'',
'        SELECT NVL(SUM(cantidad * precio_unitario), 0),',
'               NVL(SUM(monto_descuento), 0),',
'               NVL(SUM(subtotal_linea), 0),',
'               NVL(SUM(monto_impuesto), 0),',
'               NVL(SUM(monto_total_linea), 0)',
'          INTO v_subtotal_bruto, v_total_descuento, v_subtotal_neto, v_iva, v_total',
'          FROM presupuestos_det',
'         WHERE id_presupuesto = v_id_presupuesto;',
'',
'        v_gasto_real := pkg_gasto_real.fn_total_gasto_usd(v_id_presupuesto);',
'        v_desviacion := v_total - v_gasto_real;',
'        v_color := CASE WHEN v_desviacion >= 0 THEN ''#137333'' ELSE ''#c5221f'' END;',
'    END IF;',
'',
'    v_html := ''',
'    <div class="financial-summary">',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'            <span style="color: #606060; font-size: 13px;">Subtotal Bruto ('' || v_moneda || ''):</span>',
'            <strong style="color: #333333; font-size: 14px;">'' || TO_CHAR(v_subtotal_bruto, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>'';',
'',
'    v_html := v_html || ''',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'            <span style="color: #c5221f; font-size: 13px;">Descuento Total ('' || v_moneda || ''):</span>',
'            <strong style="color: #c5221f; font-size: 14px;">-'' || TO_CHAR(v_total_descuento, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'            <span style="color: #606060; font-size: 13px;">Subtotal Neto ('' || v_moneda || ''):</span>',
'            <strong style="color: #333333; font-size: 14px;">'' || TO_CHAR(v_subtotal_neto, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'            <span style="color: #606060; font-size: 13px;">Impuestos / IVA:</span>',
'            <strong style="color: #333333; font-size: 14px;">'' || TO_CHAR(v_iva, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; background-color: #40a6d4ff; color: #ffffff; font-weight: bold; font-size: 15px; border-radius: 6px; margin-top: 10px;">',
'            <span>Total ('' || v_moneda || ''):</span>',
'            <span>'' || TO_CHAR(v_total, ''FM999G999G999G990D00'') || ''</span>',
'        </div>',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px 0 0; color: #137333; font-size: 13px;">',
'            <span>Total equivalente (VES):</span>',
'            <strong>'' || TO_CHAR(v_total * v_tasa, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px 0 0; border-top: 1px solid #f0f0f0; margin-top: 8px;">',
'            <span style="color: #606060; font-size: 13px;">Gasto real:</span>',
'            <strong style="color: #333333; font-size: 14px;">'' || TO_CHAR(v_gasto_real, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 2px 0 0;">',
'            <span style="color: #606060; font-size: 13px;">Desviacion:</span>',
'            <strong style="color: '' || v_color || ''; font-size: 14px;">'' || TO_CHAR(v_desviacion, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>'';',
'',
'    v_html := v_html || ''',
'    </div>'';',
'',
'    RETURN v_html;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P5_ID_PRESUPUESTO'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Resumen Financiero'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
