,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'try {',
    '    var grid = apex.region("grid_presupuestos").widget().interactiveGrid("getViews").grid;',
    '    var records = grid.getSelectedRecords();',
    '    ',
    '    if (records.length > 0) {',
    '        var record = records[0];',
    '        var model = grid.model;',
    '        ',
    '        // Obtener la clave primaria del registro seleccionado',
    '        var pk = model.getPrimaryKey();',
    '        var id = null;',
    '        ',
    '        if (pk && pk.length > 0) {',
    '            id = model.getValue(record, pk[0]);',
    '        }',
    '        ',
    unistr('        // B\00FAsqueda alternativa si la PK viene vac\00EDa'),
    '        if (!id) {',
    '            var fields = model.getFields();',
    '            for (var i = 0; i < fields.length; i++) {',
    '                if (fields[i].name.toUpperCase().indexOf("ID") !== -1) {',
    '                    id = model.getValue(record, fields[i].name);',
    '                    if (id) break;',
    '                }',
    '            }',
    '        }',
    '        ',
    '        if (id) {',
    '            // Asignar usando APEX item y respaldar con jQuery nativo para forzar el valor',
    '            apex.item("P5_ID_PRESUPUESTO").setValue(id);',
    '            jQuery("#P5_ID_PRESUPUESTO").val(id).trigger("change");',
    '            ',
    '            console.log("ID asignado correctamente:", id);',
    '        }',
    '    } else {',
    '        apex.item("P5_ID_PRESUPUESTO").setValue("");',
    '        jQuery("#P5_ID_PRESUPUESTO").val("").trigger("change");',
    '    }',
    '} catch (e) {',
    '    console.error("Error al asignar el ID:", e);',
    '}')))).to_clob
);
