 p_id=>wwv_flow_imp.id(22585393224741113)
,p_name=>'P6_ID_IMPUESTO'
,p_source_data_type=>'NUMBER'
,p_item_sequence=>90
,p_item_plug_id=>wwv_flow_imp.id(14197242296442566)
,p_item_source_plug_id=>wwv_flow_imp.id(14197242296442566)
,p_prompt=>' Impuesto'
,p_source=>'ID_IMPUESTO'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT i.cod_pais || '' - '' || i.nombre_impuesto AS d,',
'       i.id_impuesto AS r',
'  FROM impuestos i,',
'       (SELECT (SELECT e.cod_pais',
'                  FROM empresas e',
'                 WHERE e.id_empresa = NVL((SELECT p.id_empresa',
'                                             FROM presupuestos p',
'                                            WHERE p.id_presupuesto = fn_clean_num(:P6_ID_PRESUPUESTO)),',
'                                         (SELECT MIN(u.id_empresa)',
'                                            FROM usuario u',
'                                           WHERE upper(u.username) = upper(:APP_USER)))) AS cod_pais',
'          FROM dual) pais',
' WHERE i.estado = ''ACTIVO''',
'   -- Solo los impuestos del pais de la empresa del presupuesto y, si todavia',
'   -- no hay documento (linea nueva), los del pais de la empresa del usuario.',
'   AND (pais.cod_pais IS NULL OR i.cod_pais = pais.cod_pais)',
' ORDER BY i.porcentage DESC'))
,p_lov_display_null=>'YES'
,p_lov_null_value=>'-- Seleccione Impuesto --'
,p_cSize=>30
,p_begin_on_new_line=>'N'
,p_colspan=>3
,p_field_template=>1610598304472262251
,p_item_template_options=>'#DEFAULT#'
