,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert/Update Presupuesto'
,p_static_id=>'guardar-presupuesto'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if not fn_tiene_rol(''ADMIN,GERENCIA,VENTAS,PRUEBA'') then',
'    raise_application_error(-20003, ''No tiene permisos para esta accion.'');',
'end if;',
'-- 1. Ejecutamos el procedimiento normal',
'pkg_presupuestos.prc_guardar_presupuesto(',
'    p_id_presupuesto    => :P7_ID_PRESUPUESTO,',
'    p_id_empresa        => :P7_ID_EMPRESA,',
'    p_id_cliente        => :P7_ID_CLIENTE,',
'    p_folio             => :P7_FOLIO,',
'    p_cod_moneda        => :P7_COD_MONEDA,',
'    p_fecha_vencimiento => :P7_FECHA_VENCIMIENTO,',
'    p_fecha_emision     => :P7_FECHA_EMISION,',
'    p_tipo_cambio       => :P7_TIPO_CAMBIO,',
'    p_estado            => :P7_ESTADO,',
'    p_observaciones     => :P7_OBSERVACIONES,',
'    p_usuario           => :APP_USER',
');',
'',
unistr('-- 2. El folio real lo asigno el contador de la empresa: se refresca el item'),
unistr('--    para no dejar en pantalla la vista previa (el IN OUT devuelve el id).'),
'IF :P7_ID_PRESUPUESTO IS NOT NULL THEN',
'    BEGIN',
'        SELECT folio',
'          INTO :P7_FOLIO',
'          FROM presupuestos',
'         WHERE id_presupuesto = :P7_ID_PRESUPUESTO;',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            NULL;',
'    END;',
'END IF;',
'',
unistr('-- 4. Mensaje de \00E9xito'),
'apex_application.g_print_success_message := ''Presupuesto Guardado Exitosamente (ID: '' || :P7_ID_PRESUPUESTO || '').'';'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error al guardar el presupuesto: #SQLERRM#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(14430557837287818)
,p_internal_uid=>14503700755406503
);
