wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(30554313608864005)
,p_plug_name=>'Resumen Financiero'
,p_static_id=>'totales'
,p_title=>'Resumen Financiero'
,p_region_css_classes=>'u-textRight'
,p_region_template_options=>'#DEFAULT#'
,p_region_attributes=>'style="text-align: right; font-weight: bold; font-size: 16px;"'
,p_plug_template=>3372714138756020509
,p_plug_display_sequence=>50
,p_plug_grid_column_span=>4
,p_plug_display_column=>9
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_sub_bruto    NUMBER := 0;',
'    v_tot_desc     NUMBER := 0;',
'    v_sub_neto     NUMBER := 0;',
'    v_total_imp    NUMBER := 0;',
'    v_total        NUMBER := 0;',
'    v_total_bs     NUMBER := 0;',
'    v_moneda       VARCHAR2(5);',
'    v_html         VARCHAR2(4000);',
'BEGIN',
'    -- Si el usuario no es de la empresa de la factura, no se muestra nada',
'    IF :P8_ID_FACTURAS IS NOT NULL AND NOT fn_factura_propio(:P8_ID_FACTURAS, :APP_USER) THEN',
'        RETURN NULL;',
'    END IF;',
'',
'    IF :P8_ID_FACTURAS IS NOT NULL THEN',
'        SELECT f.cod_moneda,',
'               NVL(SUM(d.cantidad * d.precio_unitario), 0),',
'               NVL(SUM(d.monto_descuento), 0),',
'               NVL(SUM(d.subtotal_linea), 0),',
'               NVL(SUM(d.monto_impuesto), 0),',
'               NVL(SUM(d.monto_total_linea), 0),',
'               NVL(SUM(d.total_bs), 0)',
'          INTO v_moneda, v_sub_bruto, v_tot_desc, v_sub_neto,',
'               v_total_imp, v_total, v_total_bs',
'          FROM facturas f',
'          LEFT JOIN facturas_det d ON d.id_factura = f.id_factura',
'         WHERE f.id_factura = fn_clean_num(:P8_ID_FACTURAS)',
'           AND f.estado NOT IN (''CANCELADA'', ''ANULADA'')',
'         GROUP BY f.cod_moneda;',
'    END IF;',
'',
'    v_moneda := NVL(v_moneda, ''---'');',
'',
unistr('    -- 3. Construcci\00F3n del HTML con el desglose completo'),
'    v_html := ''',
'    <div class="financial-summary">',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'            <span style="color: #606060; font-size: 13px;">Subtotal Bruto ('' || v_moneda || ''):</span>',
'            <strong style="color: #333333; font-size: 14px;">'' || TO_CHAR(v_sub_bruto, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>'';',
'',
'    -- Mostrar descuento solo si es mayor a cero',
'    IF v_tot_desc > 0 THEN',
'        v_html := v_html || ''',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'            <span style="color: #c5221f; font-size: 13px;">Descuento Total ('' || v_moneda || ''):</span>',
'            <strong style="color: #c5221f; font-size: 14px;">-'' || TO_CHAR(v_tot_desc, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>'';',
'    END IF;',
'',
'    v_html := v_html || ''',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'            <span style="color: #606060; font-size: 13px;">Subtotal Neto ('' || v_moneda || ''):</span>',
'            <strong style="color: #333333; font-size: 14px;">'' || TO_CHAR(v_sub_neto, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 0; border-bottom: 1px solid #f0f0f0;">',
'            <span style="color: #606060; font-size: 13px;">Impuestos / IVA:</span>',
'            <strong style="color: #333333; font-size: 14px;">'' || TO_CHAR(v_total_imp, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; background-color: #40a6d4ff; color: #ffffff; font-weight: bold; font-size: 15px; border-radius: 6px; margin-top: 10px;">',
'            <span>Total ('' || v_moneda || ''):</span>',
'            <span>'' || TO_CHAR(v_total, ''FM999G999G999G990D00'') || ''</span>',
'        </div>',
'        <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px 0 0; color: #137333; font-size: 13px;">',
'            <span>Total equivalente (VES):</span>',
'            <strong>'' || TO_CHAR(v_total_bs, ''FM999G999G999G990D00'') || ''</strong>',
'        </div>',
'    </div>'';',
'',
'    RETURN v_html;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P8_ID_FACTURAS'
);
