wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(18565092564054504)
,p_event_id=>wwv_flow_imp.id(18564965053054503)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'CALCULA_FECHA_VENC'
,p_static_id=>'calcula-fecha-venc'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P9_FECHA_VENCIMIENTO',
  'items_to_submit', 'P9_FECHA_EMISION,P9_CONDICION_PAGO',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '   ln_dias    NUMBER := 0;',
    '   ld_emision DATE;',
    'BEGIN',
    unistr('   -- 1. Validar si existe fecha de emisi\00F3n'),
    '   IF :P9_FECHA_EMISION IS NOT NULL THEN',
    unistr('      ld_emision := TO_DATE(:P9_FECHA_EMISION, ''DD/MM/YYYY''); -- o ''YYYY-MM-DD'' seg\00FAn el formato de tu \00EDtem'),
    '',
    unistr('      -- 2. Obtener los d\00EDas de cr\00E9dito seg\00FAn la condici\00F3n seleccionada'),
    '      IF :P9_CONDICION_PAGO IS NOT NULL THEN',
    '         SELECT dias_credito',
    '           INTO ln_dias',
    '           FROM condicion_pago',
    '          WHERE id_condicion_pago = :P9_CONDICION_PAGO;',
    '      END IF;',
    '',
    '      -- 3. Calcular la fecha de vencimiento',
    '      :P9_FECHA_VENCIMIENTO := TO_CHAR(ld_emision + ln_dias, ''DD/MM/YYYY'');',
    '   ELSE',
    unistr('      -- Si a\00FAn no hay fecha de emisi\00F3n, la fecha de vencimiento se blanquea'),
    '      :P9_FECHA_VENCIMIENTO := NULL;',
    '   END IF;',
    'EXCEPTION',
    '   WHEN OTHERS THEN',
    '      :P9_FECHA_VENCIMIENTO := NULL;',
    'END;')),
  'show_processing', 'N',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(18565157682054505)
,p_event_id=>wwv_flow_imp.id(18564965053054503)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_name=>'LLENA_FORMA_PAGO'
,p_static_id=>'forma-pago'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P9_FECHA_VENCIMIENTO,P9_FORMA_PAGO',
  'items_to_submit', 'P9_CONDICION_PAGO,P9_FECHA_EMISION',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '   ln_dias        NUMBER := 0;',
    '   ld_emision     DATE;',
    '   ln_id_pdef     NUMBER;',
    'BEGIN',
    '   -- 1. Obtener ID de ''POR DEFINIR''',
    '   SELECT id_forma_pago',
    '     INTO ln_id_pdef',
    '     FROM forma_pago',
    '    WHERE codigo = ''POR_DEFINIR'';',
    '',
    unistr('   -- 2. Validar Fecha de Emisi\00F3n'),
    '   IF :P9_FECHA_EMISION IS NOT NULL THEN',
    '      ld_emision := TO_DATE(:P9_FECHA_EMISION, ''DD/MM/YYYY'');',
    '',
    unistr('      -- 3. Consultar d\00EDas de cr\00E9dito de la condici\00F3n de pago'),
    '      IF :P9_CONDICION_PAGO IS NOT NULL THEN',
    '          SELECT dias_credito',
    '            INTO ln_dias',
    '            FROM condicion_pago',
    '           WHERE id_condicion_pago = :P9_CONDICION_PAGO;',
    '      END IF;',
    '',
    '      -- 4. Asignar Fecha de Vencimiento',
    '      :P9_FECHA_VENCIMIENTO := TO_CHAR(ld_emision + ln_dias, ''DD/MM/YYYY'');',
    '',
    '      -- 5. Regla de Negocio Forma de Pago',
    '      IF ln_dias > 0 THEN',
    unistr('         -- Si es a Cr\00E9dito -> Autom\00E1ticamente ''Por Definir'''),
    '         :P9_FORMA_PAGO := ln_id_pdef;',
    '      ELSE',
    '         -- Si es de Contado -> Limpiamos para que el usuario elija la forma de pago inmediata',
    '         :P9_FORMA_PAGO := NULL;',
    '      END IF;',
    '',
    '   ELSE',
    '      :P9_FECHA_VENCIMIENTO := NULL;',
    '      :P9_FORMA_PAGO := NULL;',
    '   END IF;',
    'EXCEPTION',
    '   WHEN OTHERS THEN',
    '      :P9_FECHA_VENCIMIENTO := NULL;',
    '      :P9_FORMA_PAGO := NULL;',
    'END;')),
  'show_processing', 'N',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
);
