,p_process_name=>'Carga_Presupuesto'
,p_static_id=>'carga-presupuesto'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_id_factura NUMBER;',
'BEGIN',
'    v_id_factura := :P9_ID_FACTURA;',
'    ',
unistr('    -- Si es una factura nueva y el ID a\00FAn no est\00E1 en la variable de la p\00E1gina,'),
'    -- lo rescatamos directamente de la secuencia o tabla de facturas',
'    IF v_id_factura IS NULL THEN',
'        BEGIN',
'            SELECT MAX(id_factura) ',
'              INTO v_id_factura ',
'              FROM facturas ',
unistr('             WHERE creado_por = USER; -- O la condici\00F3n que asegure el registro actual'),
'        EXCEPTION',
'            WHEN OTHERS THEN v_id_factura := NULL;',
'        END;',
'    END IF;',
'',
'    IF v_id_factura IS NOT NULL AND :P9_ID_PRESUPUESTO IS NOT NULL THEN',
'         pkg_facturacion.prc_procesar_presupuesto_factura(',
'            p_id_presupuesto_str => :P9_ID_PRESUPUESTO,',
'            p_fecha_emision_str  => :P9_FECHA_EMISION,',
'            p_id_factura         => v_id_factura,',
'            p_es_vencido         => :P9_ES_VENCIDO,',
'            p_id_empresa         => :P9_ID_EMPRESA,',
'            p_id_cliente         => :P9_ID_CLIENTE,',
'            p_subtotal           => :P9_SUBTOTAL,',
'            p_monto_impuesto     => :P9_MONTO_IMPUESTO,',
'            p_monto_total        => :P9_MONTO_TOTAL,',
'            p_cod_moneda         => :P9_COD_MONEDA,',
'            p_tipo_cambio        => :P9_TIPO_CAMBIO,',
'            p_observaciones      => :P9_OBSERVACIONES',
'        );',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'fn_tiene_rol(''ADMIN,GERENCIA,FACTURACION,PRUEBA'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>22585024194741110
);
