 p_id=>wwv_flow_imp.id(21951031791106207)
,p_name=>'P10_ID_IMPUESTO'
,p_source_data_type=>'NUMBER'
,p_item_sequence=>90
,p_item_plug_id=>wwv_flow_imp.id(36135701100546585)
,p_item_source_plug_id=>wwv_flow_imp.id(36135701100546585)
,p_prompt=>'Impuesto'
,p_source=>'ID_IMPUESTO'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT i.cod_pais || '' - '' || i.nombre_impuesto AS display_value,',
'       i.id_impuesto AS return_value',
'  FROM impuestos i,',
'       (SELECT (SELECT e.cod_pais',
'                  FROM empresas e',
'                 WHERE e.id_empresa = NVL((SELECT f.id_empresa',
'                                             FROM facturas f',
'                                            WHERE f.id_factura = fn_clean_num(:P10_ID_FACTURA)),',
'                                         (SELECT MIN(u.id_empresa)',
'                                            FROM usuario u',
'                                           WHERE upper(u.username) = upper(:APP_USER)))) AS cod_pais',
'          FROM dual) pais',
' WHERE i.estado = ''ACTIVO''',
'   AND NVL(i.es_retencion, ''N'') = ''N''',
'   AND (i.fecha_inicio IS NULL OR i.fecha_inicio <= TRUNC(SYSDATE))',
'   AND (i.fecha_fin IS NULL OR i.fecha_fin >= TRUNC(SYSDATE))',
'   -- Solo los impuestos del pais de la empresa de la factura y, si todavia',
'   -- no hay documento (linea nueva), los del pais de la empresa del usuario.',
'   AND (pais.cod_pais IS NULL OR i.cod_pais = pais.cod_pais)',
' ORDER BY i.porcentage DESC'))
,p_lov_display_null=>'YES'
,p_lov_null_value=>'-- Seleccione Impuesto --'
,p_cSize=>30


,p_field_template=>1610598304472262251
