'        SELECT NVL(NULLIF(tipo_cambio, 0), 1)',
'          INTO :P10_TASA_CAMBIO_APLICADA',
'          FROM facturas',
'         WHERE id_factura = fn_clean_num(:P10_ID_FACTURA);',
'    END IF;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
unistr('        raise_application_error(-20014, ''No se encontr\00F3 la factura para cargar su tasa de cambio.'');'),
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>22600000000000001
);
