,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(36135701100546585)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form editar detalle'
,p_static_id=>'initialize-form-editar-detalle'
,p_process_when=>'P10_ID_DETALLE'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>21946184956104084
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(21947080813104101)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert/update del Detalle'
,p_static_id=>'insert-del-detalle'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_id_factura       NUMBER := fn_clean_num(:P10_ID_FACTURA);',
'    v_id_detalle       NUMBER := fn_clean_num(:P10_ID_DETALLE);',
'    v_id_producto      NUMBER := CASE',
'                                    WHEN TRIM(:P10_ID_PRODUCTO) IS NULL THEN NULL',
'                                    ELSE fn_clean_num(:P10_ID_PRODUCTO)',
'                                 END;',
'    v_id_impuesto      NUMBER := CASE',
'                                    WHEN TRIM(:P10_ID_IMPUESTO) IS NULL THEN NULL',
'                                    ELSE fn_clean_num(:P10_ID_IMPUESTO)',
'                                 END;',
'    v_cantidad         NUMBER := fn_clean_num(:P10_CANTIDAD);',
'    v_precio_unitario  NUMBER := fn_clean_num(:P10_PRECIO_UNITARIO);',
'    v_porc_descuento   NUMBER := NVL(fn_clean_num(:P10_PORCENTAJE_DESCUENTO), 0);',
'    v_descuento_input  NUMBER := NVL(fn_clean_num(:P10_MONTO_DESCUENTO), 0);',
'    v_porc_impuesto    NUMBER := 0;',
'    v_tasa_cambio      NUMBER;',
'    v_num_linea        NUMBER;',
'    v_subtotal_bruto   NUMBER;',
'    v_monto_descuento  NUMBER;',
'    v_subtotal_linea   NUMBER;',
'    v_monto_impuesto   NUMBER;',
'    v_total_linea      NUMBER;',
'BEGIN',
'if not fn_factura_propio(:P10_ID_FACTURA, :APP_USER) then',
'    raise_application_error(-20003, ''No tiene permisos sobre este documento.'');',
'end if;',
'    IF v_id_factura IS NULL OR v_id_factura <= 0 THEN',
'        raise_application_error(-20001, ''La factura es obligatoria.'');',
'    END IF;',
'',
'    IF v_cantidad <= 0 OR v_precio_unitario < 0 THEN',
'        raise_application_error(-20002, ''La cantidad debe ser mayor que cero y el precio no puede ser negativo.'');',
'    END IF;',
'',
'    IF v_porc_descuento < 0 OR v_porc_descuento > 100 OR v_descuento_input < 0 THEN',
'        raise_application_error(-20003, ''Revise los porcentajes de descuento e impuesto.'');',
'    END IF;',
'',
'    SELECT NVL(NULLIF(tipo_cambio, 0), 1)',
'      INTO v_tasa_cambio',
'      FROM facturas',
'     WHERE id_factura = v_id_factura',
'       FOR UPDATE;',
'',
'    IF v_id_impuesto IS NOT NULL THEN',
'        BEGIN',
'            SELECT porcentage',
'              INTO v_porc_impuesto',
'              FROM impuestos',
'             WHERE id_impuesto = v_id_impuesto',
'               AND cod_pais IN (''MX'', ''VE'')',
'               AND estado = ''ACTIVO''',
'               AND NVL(es_retencion, ''N'') = ''N''',
'               AND (fecha_inicio IS NULL OR fecha_inicio <= TRUNC(SYSDATE))',
'               AND (fecha_fin IS NULL OR fecha_fin >= TRUNC(SYSDATE));',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
unistr('                raise_application_error(-20004, ''El impuesto seleccionado no est\00E1 activo o no es v\00E1lido para facturaci\00F3n.'');'),
'        END;',
'    END IF;',
'',
'    v_subtotal_bruto := ROUND(v_cantidad * v_precio_unitario, 2);',
'',
'    IF v_porc_descuento > 0 THEN',
'        v_monto_descuento := ROUND(v_subtotal_bruto * v_porc_descuento / 100, 2);',
'    ELSE',
'        v_monto_descuento := LEAST(v_subtotal_bruto, v_descuento_input);',
'        IF v_subtotal_bruto > 0 THEN',
'            v_porc_descuento := ROUND(v_monto_descuento * 100 / v_subtotal_bruto, 2);',
'        END IF;',
'    END IF;',
'',
'    v_subtotal_linea := ROUND(v_subtotal_bruto - v_monto_descuento, 2);',
'    v_monto_impuesto := ROUND(v_subtotal_linea * v_porc_impuesto / 100, 2);',
'    v_total_linea := ROUND(v_subtotal_linea + v_monto_impuesto, 2);',
'',
'    IF v_id_detalle > 0 THEN',
'        SELECT num_linea',
'          INTO v_num_linea',
'          FROM facturas_det',
'         WHERE id_detalle = v_id_detalle',
'           AND id_factura = v_id_factura;',
'',
'        UPDATE facturas_det',
'           SET id_producto = v_id_producto,',
'               codigo_producto = :P10_CODIGO_PRODUCTO,',
'               descripcion = :P10_DESCRIPCION,',
'               cantidad = v_cantidad,',
'               precio_unitario = v_precio_unitario,',
'               porcentaje_descuento = v_porc_descuento,',
'               monto_descuento = v_monto_descuento,',
'               id_impuesto = v_id_impuesto,',
'               porcentaje_impuesto = v_porc_impuesto,',
'               monto_impuesto = v_monto_impuesto,',
'               subtotal_linea = v_subtotal_linea,',
'               monto_total_linea = v_total_linea,',
'               tasa_cambio_aplicada = v_tasa_cambio,',
'               subtotal_bs = ROUND(v_subtotal_linea * v_tasa_cambio, 2),',
'               total_bs = ROUND(v_total_linea * v_tasa_cambio, 2)',
'         WHERE id_detalle = v_id_detalle',
'           AND id_factura = v_id_factura;',
'    ELSE',
'        SELECT NVL(MAX(num_linea), 0) + 1',
'          INTO v_num_linea',
'          FROM facturas_det',
'         WHERE id_factura = v_id_factura;',
'',
'        INSERT INTO facturas_det (',
'            id_factura, num_linea, id_producto, codigo_producto, descripcion,',
'            cantidad, precio_unitario, porcentaje_descuento, monto_descuento,',
'            id_impuesto, porcentaje_impuesto, monto_impuesto, subtotal_linea,',
'            monto_total_linea, tasa_cambio_aplicada, subtotal_bs, total_bs, creado_por',
'        ) VALUES (',
'            v_id_factura, v_num_linea, v_id_producto, :P10_CODIGO_PRODUCTO,',
'            :P10_DESCRIPCION, v_cantidad, v_precio_unitario, v_porc_descuento,',
'            v_monto_descuento, v_id_impuesto, v_porc_impuesto, v_monto_impuesto,',
'            v_subtotal_linea, v_total_linea, v_tasa_cambio,',
'            ROUND(v_subtotal_linea * v_tasa_cambio, 2),',
'            ROUND(v_total_linea * v_tasa_cambio, 2), :APP_USER',
'        )',
'        RETURNING id_detalle INTO v_id_detalle;',
'',
'        :P10_ID_DETALLE := v_id_detalle;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error al guardar el Detalle de la Factura: #SQLERRM#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'fn_tiene_rol(''ADMIN,GERENCIA,FACTURACION,PRUEBA'') and :REQUEST in (''CREATE'',''SAVE'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>21947080813104101
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(43000000000000016)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Valida rol: ver facturacion detalle'
,p_static_id=>'valida-rol-ver-facturacion-det'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if not fn_tiene_rol(''ADMIN,GERENCIA,FACTURACION,CONSULTA,PRUEBA'') then',
'    raise_application_error(-20003, ''No tiene permisos para esta pagina.'');',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>43000000000000016
);
end;
