wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(23600000000000020)
,p_plug_name=>'Facturacion 6 meses'
,p_static_id=>'facturacion-6-meses'
,p_title=>unistr('Facturaci\00F3n de los \00FAltimos 6 meses')
,p_region_css_classes=>'metric-card'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_escape_on_http_output=>'Y'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>30
,p_plug_grid_column_span=>7
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH meses AS (',
'  SELECT ADD_MONTHS(TRUNC(SYSDATE,''MM''), -5 + LEVEL - 1) AS mes',
'    FROM dual CONNECT BY LEVEL <= 6)',
'SELECT TO_CHAR(m.mes,''MM/YYYY'') AS label,',
'       NVL(SUM(CASE WHEN f.tipo_documento = ''NC'' THEN -f.monto_total ELSE f.monto_total END),0) AS value',
'  FROM meses m',
'  LEFT JOIN facturas f',
'    ON TRUNC(f.fecha_emision,''MM'') = m.mes',
'   AND f.id_empresa = :P13_ID_EMPRESA',
'   AND f.cod_moneda = :P13_MONEDA',
'   AND f.tipo_documento IN (''FAC'',''NC'',''ND'')',
'   AND f.estado <> ''ANULADA''',
' GROUP BY m.mes',
' ORDER BY m.mes'))
,p_plug_source_type=>'NATIVE_JET_CHART'
);
