wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(43000000000000047)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Restablecer contrase\00F1a')
,p_static_id=>'restablecer-password'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_obligatorio varchar2(1) := ''N'';',
'    v_email       varchar2(100);',
'begin',
'    begin',
'        select nvl(debe_cambiar_clave, ''N'')',
'          into v_obligatorio',
'          from usuario',
'         where upper(username) = upper(v(''APP_USER''));',
'    exception',
'        when no_data_found then v_obligatorio := ''N'';',
'    end;',
'',
'    if :P14_PASSWORD <> :P14_PASSWORD_CONFIRM then',
unistr('    raise_application_error(-20011, ''Las contrase\00F1as no coinciden.'');'),
'    end if;',
'',
'    if length(:P14_PASSWORD) < 8',
'       or not regexp_like(:P14_PASSWORD, ''[[:alpha:]]'')',
'       or not regexp_like(:P14_PASSWORD, ''[[:digit:]]'') then',
unistr('    raise_application_error(-20012, ''La contrase\00F1a debe tener al menos 8 caracteres y combinar letras y numeros.'');'),
'    end if;',
'',
'    if v_obligatorio = ''S'' then',
'        update usuario',
'           set password_hash      = sypex_hash_password(:P14_PASSWORD),',
'               debe_cambiar_clave = ''N'',',
'               reintentos_fallidos = 0,',
'               bloqueado_hasta    = null',
'         where upper(username) = upper(v(''APP_USER''));',
'',
'        if sql%rowcount = 0 then',
'            raise_application_error(-20010, ''Los datos no coinciden con un usuario activo.'');',
'        end if;',
'',
'        select email into v_email',
'          from usuario',
'         where upper(username) = upper(v(''APP_USER''));',
'',
'        prc_log_reset_password(',
'            p_usuario   => v(''APP_USER''),',
'            p_correo    => v_email,',
'            p_ip        => owa_util.get_cgi_env(''REMOTE_ADDR''),',
'            p_resultado => ''OK'');',
'',
'        apex_util.set_session_state(''F_DEBE_CAMBIAR_CLAVE'', ''N'');',
'        apex_util.set_session_state(''P14_MODO_OBLIG'', ''OK'');',
unistr('        apex_application.g_print_success_message := ''Contrase\00F1a actualizada. Bienvenido.'';'),
'        return;',
'    end if;',
'',
'    update usuario',
'       set password_hash = sypex_hash_password(:P14_PASSWORD),',
'           reintentos_fallidos = 0,',
'           bloqueado_hasta = null',
'     where upper(username) = upper(:P14_USERNAME)',
